-- Fresh dataplane resource/state schema. Managed execution belongs exclusively to ma.
-- Unreleased Service refactoring: use a fresh data space; no legacy runtime conversion.
create table builder_agent (group_chat_require_mention boolean, head_version integer not null, max_iters integer, archived_at bigint, created_at bigint, row_id bigint generated by default as identity, updated_at bigint, sandbox_mode varchar(16), sandbox_scope varchar(16), run_as varchar(20), identity_emoji varchar(32), model varchar(100), agent_id varchar(128) not null, fork_of varchar(128), owner_id varchar(128) not null, identity_name varchar(200), name varchar(200), workspace_path varchar(1024), description oid, group_chat_mention_patterns_json oid, permission_policies_json oid, skill_repositories_json oid, skills_allow_json oid, skills_deny_json oid, sys_prompt oid, tools_allow_json oid, tools_deny_json oid, primary key (row_id), constraint ux_builder_agent_owner_agent unique (owner_id, agent_id));
create table builder_agent_share (agent_row_id bigint not null, created_at bigint, id bigint generated by default as identity, grantee_type varchar(20) not null, tier varchar(20) not null, created_by varchar(128), grantee_id varchar(128) not null, primary key (id));
create table builder_agent_state (list_kind boolean not null, row_id bigint generated by default as identity, updated_at bigint not null, user_id varchar(128) not null, session_id varchar(255) not null, state_key varchar(255) not null, state_data oid not null, primary key (row_id), constraint uk_builder_agent_state_slot unique (user_id, session_id, state_key));
create table builder_agent_version (version integer not null, created_at bigint not null, row_id bigint generated by default as identity, agent_id varchar(128) not null, owner_id varchar(128) not null, snapshot_json oid not null, primary key (row_id), constraint ux_builder_agent_version unique (owner_id, agent_id, version));
create table builder_deployment (agent_version integer, enabled boolean not null, archived_at bigint, created_at bigint not null, last_run_at bigint, row_id bigint generated by default as identity, updated_at bigint not null, last_status varchar(32), trigger_type varchar(32) not null, deployment_id varchar(64) not null unique, environment_id varchar(64) not null, last_session_id varchar(64), agent_id varchar(128) not null, cron_expression varchar(128), owner_id varchar(128) not null, webhook_token varchar(128) unique, name varchar(200) not null, primary key (row_id));
create table builder_environment (archived_at bigint, created_at bigint not null, row_id bigint generated by default as identity, updated_at bigint not null, type varchar(32) not null, api_key_hash varchar(64), environment_id varchar(64) not null unique, owner_id varchar(128) not null, name varchar(200) not null, config_json oid, primary key (row_id), constraint ux_builder_environment_owner_name unique (owner_id, name));
create table builder_memory (head_version integer not null, created_at bigint not null, row_id bigint generated by default as identity, updated_at bigint not null, memory_id varchar(64) not null unique, store_id varchar(64) not null, path varchar(512) not null, content oid, primary key (row_id), constraint ux_builder_memory_store_path unique (store_id, path));
create table builder_memory_store (created_at bigint not null, row_id bigint generated by default as identity, updated_at bigint not null, store_id varchar(64) not null unique, owner_id varchar(128) not null, name varchar(200) not null, description oid, primary key (row_id), constraint ux_builder_memory_store_owner_name unique (owner_id, name));
create table builder_memory_version (version integer not null, created_at bigint not null, row_id bigint generated by default as identity, memory_id varchar(64) not null, content oid, primary key (row_id), constraint ux_builder_memory_version unique (memory_id, version));
create table builder_resource_share (created_at bigint not null, row_id bigint generated by default as identity, grantee_type varchar(16) not null, tier varchar(16) not null, resource_type varchar(32) not null, resource_id varchar(64) not null, share_id varchar(64) not null unique, created_by varchar(128), grantee_id varchar(128) not null, owner_id varchar(128) not null, primary key (row_id), constraint ux_builder_resource_share_grant unique (resource_type, resource_id, grantee_type, grantee_id));
create table builder_session (agent_version integer, archived_at bigint, created_at bigint not null, row_id bigint generated by default as identity, updated_at bigint not null, version bigint, agent_ref_type varchar(32) not null, status varchar(32) not null, environment_id varchar(64) not null, session_id varchar(64) not null unique, agent_id varchar(128) not null, agent_owner_id varchar(128), owner_id varchar(128) not null, external_key varchar(256), agent_overrides_json oid, memory_store_ids_json oid, resources_json oid, stop_reason_json oid, vault_ids_json oid, primary key (row_id));
create table builder_session_event (created_at bigint not null, processed_at bigint, row_id bigint generated by default as identity, seq bigint not null, event_id varchar(64) not null unique, event_type varchar(64) not null, session_id varchar(64) not null, payload_json TEXT, primary key (row_id), constraint ux_builder_session_event_seq unique (session_id, seq));
create table builder_user (created_at timestamp(6) with time zone, user_id varchar(128) not null, username varchar(191) not null, password_hash varchar(200) not null, roles_csv varchar(500), primary key (user_id), constraint ix_builder_user_username unique (username));
create table builder_user_marketplace (created_at timestamp(6) with time zone, id bigint generated by default as identity, updated_at timestamp(6) with time zone, type varchar(32) not null, marketplace_id varchar(128) not null, user_id varchar(128) not null, properties_json oid, primary key (id), constraint uk_user_marketplace unique (user_id, marketplace_id));
create table builder_vault (created_at bigint not null, row_id bigint generated by default as identity, updated_at bigint not null, vault_id varchar(64) not null unique, owner_id varchar(128) not null, display_name varchar(200) not null, metadata_json oid, primary key (row_id));
create table builder_vault_credential (created_at bigint not null, row_id bigint generated by default as identity, updated_at bigint not null, credential_id varchar(64) not null unique, credential_type varchar(64) not null, vault_id varchar(64) not null, label varchar(200), target varchar(200), ciphertext oid not null, primary key (row_id));
create index ix_builder_agent_owner on builder_agent (owner_id);
create index ix_builder_agent_agent_id on builder_agent (agent_id);
create index ix_agent_share_grantee on builder_agent_share (grantee_type, grantee_id);
create index ix_builder_agent_state_user on builder_agent_state (user_id);
create index ix_builder_agent_state_user_session on builder_agent_state (user_id, session_id);
create index ix_builder_agent_version_owner_agent on builder_agent_version (owner_id, agent_id);
create index ix_builder_deployment_owner on builder_deployment (owner_id);
create index ix_builder_deployment_agent on builder_deployment (agent_id);
create index ix_builder_deployment_webhook_token on builder_deployment (webhook_token);
create index ix_builder_environment_owner on builder_environment (owner_id);
create index ix_builder_memory_store on builder_memory (store_id);
create index ix_builder_memory_store_owner on builder_memory_store (owner_id);
create index ix_builder_memory_version_memory on builder_memory_version (memory_id);
create index ix_builder_resource_share_resource on builder_resource_share (resource_type, resource_id);
create index ix_builder_session_owner on builder_session (owner_id);
create index ix_builder_session_agent on builder_session (agent_id);
create index ix_builder_session_env on builder_session (environment_id);
create index ix_builder_session_external_key on builder_session (external_key);
create index ix_builder_session_event_session on builder_session_event (session_id);
create index ix_builder_session_event_type on builder_session_event (event_type);
create index ix_user_marketplace_user on builder_user_marketplace (user_id);
create index ix_builder_vault_owner on builder_vault (owner_id);
create index ix_builder_vault_cred_vault on builder_vault_credential (vault_id);
alter table if exists builder_agent_share add constraint fk_share_agent foreign key (agent_row_id) references builder_agent;

CREATE TABLE IF NOT EXISTS agentscope_store (  namespace_path VARCHAR(2048) NOT NULL,  item_key       VARCHAR(255)  NOT NULL,  value_json     TEXT          NOT NULL,  version        BIGINT        NOT NULL,  updated_at     BIGINT        NOT NULL,  PRIMARY KEY (namespace_path, item_key));
CREATE INDEX IF NOT EXISTS agentscope_store_namespace_idx ON agentscope_store (namespace_path);
CREATE TABLE IF NOT EXISTS agentscope_sessions (  session_id  VARCHAR(255) NOT NULL,  state_key   VARCHAR(255) NOT NULL,  item_index  INT          NOT NULL DEFAULT 0,  state_data  TEXT         NOT NULL,  version     BIGINT       NOT NULL DEFAULT 0,  created_at  TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,  updated_at  TIMESTAMP    DEFAULT CURRENT_TIMESTAMP,  PRIMARY KEY (session_id, state_key, item_index));
CREATE INDEX IF NOT EXISTS agentscope_sessions_session_idx ON agentscope_sessions (session_id);
CREATE TABLE IF NOT EXISTS agentscope_snapshots (  snapshot_id VARCHAR(512) NOT NULL PRIMARY KEY,   data BYTEA NOT NULL,   created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
